using InventorySystem.Domain.Common; namespace InventorySystem.Domain.Entities; public sealed class Personnel:BaseEntity { private Personnel(){} public Personnel(string sicilNo,string ad,string soyad,string departman,string pozisyon,string? eposta,string? zimmetNo,bool aktifMi){ApplyChanges(sicilNo,ad,soyad,departman,pozisyon,eposta,zimmetNo,aktifMi);} public string SicilNo{get;private set;}=string.Empty; public string Ad{get;private set;}=string.Empty; public string Soyad{get;private set;}=string.Empty; public string Departman{get;private set;}=string.Empty; public string Pozisyon{get;private set;}=string.Empty; public string? Eposta{get;private set;} public string? ZimmetNo{get;private set;} public bool AktifMi{get;private set;} public void Update(string s,string a,string so,string d,string p,string? e,string? z,bool active,DateTimeOffset u){ApplyChanges(s,a,so,d,p,e,z,active);UpdatedAt=u;} public void SoftDelete(DateTimeOffset d){IsDeleted=true;DeletedAt=d;UpdatedAt=d;AktifMi=false;} private void ApplyChanges(string s,string a,string so,string d,string p,string? e,string? z,bool active){SicilNo=s.Trim().ToUpperInvariant();Ad=a.Trim();Soyad=so.Trim();Departman=d.Trim();Pozisyon=p.Trim();Eposta=string.IsNullOrWhiteSpace(e)?null:e.Trim();ZimmetNo=string.IsNullOrWhiteSpace(z)?null:z.Trim();AktifMi=active;} }
